(function () {
'use strict';

/* ---------- Embedded assets (offline) ---------- */
var CHARS = [
  { name: 'Ronaldoo!!',      src: 'data:image/png;base64,' },
  { name: 'Thaanuf',         src: 'data:image/png;base64,' },
  { name: 'Ebin jose perera', src: 'data:image/png;base64,' }
];
/* Game-over audio: paste the Base64 of your audio file between the quotes.
   Either a full data URI ("data:audio/mpeg;base64,....") or the raw Base64 text. */
var GAMEOVER_AUDIO = 'data:audio/mpeg;base64,';

/* ---------- Helpers ---------- */
var $ = function (id) { return document.getElementById(id); };
var W = 360, H = 560;
var cv = $('cv'), ctx = cv.getContext('2d');
var dpr = Math.min(window.devicePixelRatio || 1, 2);
cv.width = W * dpr; cv.height = H * dpr; ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

var imgs = CHARS.map(function (c) { var i = new Image(); i.src = c.src; return i; });
var S = { sel: [-1, -1], game: null, turn: 0, state: 'idle', raf: 0, last: 0, muted: false, G: null, score: 0, overTimer: 0 };
var GN = { flappy: 'Flappy ERE', dino: 'Dino ERE' };

function store(k, v) { try { if (v === undefined) return localStorage.getItem(k); localStorage.setItem(k, v); } catch (e) {} return null; }
S.muted = store('ere_muted') === '1';
function bestKey(g, p) { return 'ere_best_' + g + '_p' + (p + 1); }
function getBest(g, p) { return parseInt(store(bestKey(g, p)), 10) || 0; }
function pName(p) { return 'Player ' + (p + 1) + ' · ' + CHARS[S.sel[p]].name; }
function rnd(a, b) { return a + Math.random() * (b - a); }

/* ---------- Audio (Web Audio API) ---------- */
var AC = null;
function audio() {
  if (!AC) { try { AC = new (window.AudioContext || window.webkitAudioContext)(); } catch (e) { AC = null; } }
  if (AC && AC.state === 'suspended') AC.resume();
  return AC;
}
function tone(f, d, type, vol, slide, delay) {
  if (S.muted) return; var a = audio(); if (!a) return;
  var t = a.currentTime + (delay || 0), o = a.createOscillator(), g = a.createGain();
  o.type = type || 'square'; o.frequency.setValueAtTime(f, t);
  if (slide) o.frequency.exponentialRampToValueAtTime(Math.max(30, slide), t + d);
  g.gain.setValueAtTime(vol || 0.12, t); g.gain.exponentialRampToValueAtTime(0.0001, t + d);
  o.connect(g); g.connect(a.destination); o.start(t); o.stop(t + d + 0.02);
}
var SFX = {
  click: function () { tone(660, 0.07, 'square', 0.1); },
  select: function () { tone(523, 0.08, 'triangle', 0.15); tone(784, 0.1, 'triangle', 0.15, 0, 0.07); },
  start: function () { [392, 523, 659, 784].forEach(function (f, i) { tone(f, 0.12, 'square', 0.1, 0, i * 0.09); }); },
  flap: function () { tone(380, 0.12, 'sine', 0.16, 720); },
  jump: function () { tone(250, 0.18, 'square', 0.09, 560); },
  score: function () { tone(988, 0.07, 'square', 0.09); tone(1319, 0.12, 'square', 0.09, 0, 0.07); },
  hit: function () { tone(180, 0.3, 'sawtooth', 0.2, 40); }
};
var overEl = null;
function playGameOver() {
  if (S.muted || !GAMEOVER_AUDIO) return;
  try {
    var src = GAMEOVER_AUDIO.indexOf('data:') === 0 ? GAMEOVER_AUDIO : 'data:audio/mpeg;base64,' + GAMEOVER_AUDIO;
    if (!overEl) overEl = new Audio(src);
    overEl.pause(); overEl.currentTime = 0;
    var p = overEl.play(); if (p && p.catch) p.catch(function () {});
  } catch (e) {}
}
function stopGameOver() { if (overEl) { try { overEl.pause(); overEl.currentTime = 0; } catch (e) {} } }
function paintMute() { $('muteBtn').textContent = S.muted ? '🔇' : '🔊'; }
$('muteBtn').addEventListener('click', function () {
  S.muted = !S.muted; store('ere_muted', S.muted ? '1' : '0'); paintMute();
  if (S.muted) stopGameOver(); else SFX.click();
});
paintMute();

/* ---------- Screens ---------- */
function show(id) {
  var s = document.querySelectorAll('.screen');
  for (var i = 0; i < s.length; i++) s[i].classList.toggle('active', s[i].id === id);
  if (id !== 'play') stopLoop();
  if (id === 'games') { $('bestF').textContent = bestText('flappy'); $('bestD').textContent = bestText('dino'); }
  if (id === 'play') fit();
}
function bestText(g) { return 'Best  P1 ' + getBest(g, 0) + '  |  P2 ' + getBest(g, 1); }

/* welcome heads + character cards */
CHARS.forEach(function (c) { var i = document.createElement('img'); i.src = c.src; i.alt = c.name; $('welcomeHeads').appendChild(i); });
[0, 1].forEach(function (p) {
  var box = $('cards' + p);
  CHARS.forEach(function (c, ci) {
    var b = document.createElement('button'); b.className = 'card'; b.type = 'button';
    b.innerHTML = '<img alt=""><span></span>';
    b.firstChild.src = c.src; b.lastChild.textContent = c.name;
    b.addEventListener('click', function () {
      S.sel[p] = ci; SFX.select();
      var all = box.children; for (var k = 0; k < all.length; k++) all[k].classList.toggle('sel', k === ci);
      $('toGames').disabled = S.sel[0] < 0 || S.sel[1] < 0;
    });
    box.appendChild(b);
  });
});

$('startBtn').addEventListener('click', function () { audio(); SFX.click(); show('select'); });
$('toGames').addEventListener('click', function () { SFX.click(); show('games'); });
Array.prototype.forEach.call(document.querySelectorAll('[data-go]'), function (b) {
  b.addEventListener('click', function () { SFX.click(); show(b.getAttribute('data-go')); });
});
Array.prototype.forEach.call(document.querySelectorAll('[data-game]'), function (b) {
  b.addEventListener('click', function () { S.game = b.getAttribute('data-game'); S.turn = 0; SFX.start(); startRound(); });
});
function goHome() { stopGameOver(); clearTimeout(S.overTimer); SFX.click(); S.state = 'idle'; show('welcome'); }
$('homeBtn').addEventListener('click', goHome);
$('homeBtn2').addEventListener('click', goHome);
$('restartBtn').addEventListener('click', function () { stopGameOver(); SFX.start(); S.turn = 1 - S.turn; startRound(); });

/* ---------- Canvas fit ---------- */
function fit() {
  var st = $('stage'); var aw = st.clientWidth, ah = st.clientHeight; if (!aw || !ah) return;
  var s = Math.min(aw / W, ah / H); cv.style.width = Math.floor(W * s) + 'px'; cv.style.height = Math.floor(H * s) + 'px';
  var o = $('overPanel'); o.style.width = cv.style.width; o.style.height = cv.style.height;
}
window.addEventListener('resize', fit);
window.addEventListener('orientationchange', function () { setTimeout(fit, 200); });

/* ---------- Round control ---------- */
function stopLoop() { if (S.raf) { cancelAnimationFrame(S.raf); S.raf = 0; } }
function startLoop() { stopLoop(); S.last = performance.now(); S.raf = requestAnimationFrame(loop); }

function startRound() {
  clearTimeout(S.overTimer); stopGameOver();
  S.score = 0; S.state = 'ready';
  S.G = S.game === 'flappy' ? newFlappy() : newDino();
  $('overPanel').hidden = true;
  $('actBtn').textContent = S.game === 'flappy' ? 'Flap' : 'Jump';
  $('turnLabel').textContent = pName(S.turn) + "'s turn"; $('turnLabel').className = 'turn t' + S.turn;
  $('scoreNow').textContent = '0'; $('bestNow').textContent = 'Best ' + getBest(S.game, S.turn);
  show('play'); fit(); startLoop();
}

function act() {
  audio();
  if (S.state === 'ready') S.state = 'run';
  if (S.state !== 'run') return;
  if (S.game === 'flappy') flap(); else jump();
}
function addScore(n) {
  S.score += n; $('scoreNow').textContent = S.score;
  var b = getBest(S.game, S.turn); if (S.score > b) $('bestNow').textContent = 'Best ' + S.score;
}
function die() {
  if (S.state === 'dead') return; S.state = 'dead';
  SFX.hit();
  var b = getBest(S.game, S.turn), isNew = S.score > b;
  if (isNew) { b = S.score; store(bestKey(S.game, S.turn), String(b)); }
  S.overTimer = setTimeout(function () {
    if (S.state !== 'dead') return;
    playGameOver();
    $('overWho').textContent = pName(S.turn);
    $('overScore').textContent = S.score;
    $('overBest').textContent = (isNew && S.score > 0 ? 'New best: ' : 'Best: ') + b;
    $('overBoth').textContent = 'P1 best ' + getBest(S.game, 0) + '  |  P2 best ' + getBest(S.game, 1);
    $('restartBtn').textContent = 'Restart: ' + pName(1 - S.turn).split(' · ')[0] + "'s turn";
    $('overPanel').hidden = false;
  }, 350);
}

/* ---------- Input ---------- */
document.addEventListener('keydown', function (e) {
  if (!$('play').classList.contains('active')) return;
  if (e.code === 'Space' || e.code === 'ArrowUp' || e.key === ' ') {
    e.preventDefault(); if (!e.repeat) act();
  }
});
function press(el) {
  el.addEventListener('pointerdown', function (e) { e.preventDefault(); act(); });
}
press(cv); press($('actBtn'));
$('actBtn').addEventListener('keydown', function (e) { if (e.code === 'Space' || e.code === 'Enter') e.preventDefault(); });
document.addEventListener('touchmove', function (e) { if ($('play').classList.contains('active')) e.preventDefault(); }, { passive: false });
document.addEventListener('contextmenu', function (e) { e.preventDefault(); });
document.addEventListener('visibilitychange', function () { S.last = performance.now(); });

/* ---------- Loop ---------- */
function loop(t) {
  S.raf = requestAnimationFrame(loop);
  var dt = Math.min((t - S.last) / 16.667, 2.5); S.last = t; if (dt < 0) dt = 0;
  if (S.state === 'ready' || S.state === 'run') { S.game === 'flappy' ? updFlappy(dt) : updDino(dt); }
  S.game === 'flappy' ? drawFlappy() : drawDino();
  if (S.state === 'dead' && S.G.settle <= 0) stopLoop();
}

/* shared drawing */
function face(i, cx, cy, w, h, rot, ring) {
  ctx.save(); ctx.translate(cx, cy); if (rot) ctx.rotate(rot);
  ctx.beginPath(); ctx.ellipse(0, 0, w / 2, h / 2, 0, 0, 6.2832); ctx.closePath();
  ctx.fillStyle = '#ffd9b0'; ctx.fill();
  ctx.save(); ctx.clip();
  var im = imgs[i];
  if (im.complete && im.naturalWidth) {
    var r = im.naturalWidth / im.naturalHeight, dw = w, dh = w / r; if (dh < h) { dh = h; dw = h * r; }
    ctx.drawImage(im, -dw / 2, -dh / 2, dw, dh);
  }
  ctx.restore();
  ctx.lineWidth = 3; ctx.strokeStyle = ring || '#fff'; ctx.stroke(); ctx.restore();
}
function cloud(x, y, s) {
  ctx.fillStyle = 'rgba(255,255,255,.85)'; ctx.beginPath();
  ctx.arc(x, y, 14 * s, 0, 6.3); ctx.arc(x + 16 * s, y - 8 * s, 18 * s, 0, 6.3); ctx.arc(x + 36 * s, y, 14 * s, 0, 6.3); ctx.fill();
}
function hitCircleRect(cx, cy, r, rx, ry, rw, rh) {
  var nx = Math.max(rx, Math.min(cx, rx + rw)), ny = Math.max(ry, Math.min(cy, ry + rh));
  var dx = cx - nx, dy = cy - ny; return dx * dx + dy * dy < r * r;
}
function centerText(txt, y, size, col) {
  ctx.font = '900 ' + size + 'px Impact,"Arial Black",sans-serif'; ctx.textAlign = 'center';
  ctx.lineWidth = 6; ctx.strokeStyle = '#1a0b45'; ctx.strokeText(txt, W / 2, y); ctx.fillStyle = col || '#fff'; ctx.fillText(txt, W / 2, y);
}

/* ---------- FLAPPY ERE ---------- */
var F_GROUND = H - 70, F_BX = 95, F_R = 17;
function newFlappy() {
  return { y: H / 2 - 30, vy: 0, pipes: [], speed: 2.4, gx: 0, cx: 0, t: 0, settle: 40 };
}
function flap() { S.G.vy = -7.4; SFX.flap(); }
function updFlappy(dt) {
  var g = S.G; g.t += dt; g.cx = (g.cx + 0.3 * dt) % 500;
  if (S.state === 'ready') { g.y = H / 2 - 30 + Math.sin(g.t * 0.1) * 8; g.gx = (g.gx + g.speed * dt) % 24; return; }
  g.speed = Math.min(4.8, 2.4 + S.score * 0.07); g.gx = (g.gx + g.speed * dt) % 24;
  g.vy = Math.min(g.vy + 0.46 * dt, 10); g.y += g.vy * dt;
  if (g.y < F_R) { g.y = F_R; g.vy = 0; }
  var last = g.pipes[g.pipes.length - 1];
  if (!last || last.x < W - 195) {
    var gap = Math.max(118, 178 - S.score * 2.2);
    g.pipes.push({ x: W + 10, gap: gap, top: rnd(70, F_GROUND - 70 - gap), passed: false });
  }
  for (var i = g.pipes.length - 1; i >= 0; i--) {
    var p = g.pipes[i]; p.x -= g.speed * dt;
    if (p.x < -70) { g.pipes.splice(i, 1); continue; }
    if (!p.passed && p.x + 56 < F_BX - F_R) { p.passed = true; addScore(1); SFX.score(); }
    var r = F_R - 3;
    if (hitCircleRect(F_BX, g.y, r, p.x, -10, 56, p.top + 10) || hitCircleRect(F_BX, g.y, r, p.x, p.top + p.gap, 56, H)) { die(); }
  }
  if (g.y > F_GROUND - F_R) { g.y = F_GROUND - F_R; die(); }
  if (S.state === 'dead') g.vy = Math.max(g.vy, 2);
}
function drawFlappy() {
  var g = S.G, i;
  var sky = ctx.createLinearGradient(0, 0, 0, H); sky.addColorStop(0, '#4fb3ff'); sky.addColorStop(1, '#bff0ff');
  ctx.fillStyle = sky; ctx.fillRect(0, 0, W, H);
  for (i = 0; i < 3; i++) cloud(((i * 190 - g.cx * 1.2) % 560 + 560) % 560 - 60, 90 + i * 70, 1 + i * 0.2);
  for (i = 0; i < g.pipes.length; i++) {
    var p = g.pipes[i];
    ctx.fillStyle = '#3ccf4e'; ctx.strokeStyle = '#1a0b45'; ctx.lineWidth = 3;
    ctx.fillRect(p.x, -5, 56, p.top + 5); ctx.strokeRect(p.x, -5, 56, p.top + 5);
    ctx.fillRect(p.x - 5, p.top - 24, 66, 24); ctx.strokeRect(p.x - 5, p.top - 24, 66, 24);
    var by = p.top + p.gap;
    ctx.fillRect(p.x, by, 56, F_GROUND - by); ctx.strokeRect(p.x, by, 56, F_GROUND - by);
    ctx.fillRect(p.x - 5, by, 66, 24); ctx.strokeRect(p.x - 5, by, 66, 24);
    ctx.fillStyle = 'rgba(255,255,255,.35)'; ctx.fillRect(p.x + 8, 0, 8, p.top - 24); ctx.fillRect(p.x + 8, by + 24, 8, F_GROUND - by - 24);
  }
  ctx.fillStyle = '#e8c872'; ctx.fillRect(0, F_GROUND, W, H - F_GROUND);
  ctx.fillStyle = '#7ddb4a'; ctx.fillRect(0, F_GROUND, W, 14);
  ctx.fillStyle = '#5bb533'; for (i = -1; i < 16; i++) ctx.fillRect(i * 24 - g.gx, F_GROUND + 4, 12, 6);
  ctx.fillStyle = '#1a0b45'; ctx.fillRect(0, F_GROUND - 2, W, 3);
  var rot = S.state === 'ready' ? 0 : Math.max(-0.5, Math.min(1.1, g.vy * 0.09));
  face(S.sel[S.turn], F_BX, g.y, F_R * 2.3, F_R * 2.6, rot, S.turn ? '#2de2e6' : '#ff3d81');
  if (S.state === 'ready') { centerText('TAP TO FLAP', 150, 34, '#ffd23f'); }
  else if (S.state === 'run') { centerText(String(S.score), 70, 48, '#fff'); }
  if (S.state === 'dead') { if (g.settle > 0) { g.settle -= 1; g.vy = Math.min(g.vy + 0.5, 10); g.y = Math.min(g.y + g.vy, F_GROUND - F_R); } }
}

/* ---------- DINO ERE ---------- */
var D_GY = H - 110, D_X = 70, D_W = 40, D_H = 58;
function newDino() {
  return { y: 0, vy: 0, obs: [], speed: 6, dist: 0, gap: 300, t: 0, gx: 0, cx: 0, settle: 1 };
}
function jump() { var g = S.G; if (g.y <= 0.5) { g.vy = 13.6; SFX.jump(); } }
function updDino(dt) {
  var g = S.G; g.t += dt; g.cx = (g.cx + 0.4 * dt) % 600;
  if (S.state === 'ready') return;
  g.speed = Math.min(13.5, 6 + S.score / 55);
  g.gx = (g.gx + g.speed * dt) % 40; g.dist += g.speed * dt;
  var ns = Math.floor(g.dist / 14);
  if (ns > S.score) { var old = S.score; addScore(ns - S.score); if (Math.floor(ns / 100) > Math.floor(old / 100)) SFX.score(); }
  g.y += g.vy * dt; g.vy -= 0.78 * dt; if (g.y <= 0) { g.y = 0; g.vy = 0; }
  var last = g.obs[g.obs.length - 1];
  if (!last || last.x < W - g.gap) {
    var r = Math.random(), o;
    if (S.score > 120 && r < 0.28) { var hi = Math.random() < 0.5; o = { k: 'bird', w: 42, h: 28, x: W + 20, lift: hi ? 92 : 26 }; }
    else if (r < 0.55) o = { k: 'cactus', w: 24, h: 46, x: W + 20, lift: 0, n: 1 };
    else if (r < 0.8) o = { k: 'cactus', w: 30, h: 64, x: W + 20, lift: 0, n: 1 };
    else o = { k: 'cactus', w: 66, h: 48, x: W + 20, lift: 0, n: 3 };
    g.obs.push(o); g.gap = g.speed * 38 + rnd(90, 300);
  }
  for (var i = g.obs.length - 1; i >= 0; i--) {
    var b = g.obs[i]; b.x -= g.speed * dt * (b.k === 'bird' ? 1.12 : 1);
    if (b.x < -90) { g.obs.splice(i, 1); continue; }
    var px = D_X + 7, pw = D_W - 14, py = D_GY - g.y - D_H + 6, ph = D_H - 10;
    var bx = b.x + 4, bw = b.w - 8, by = D_GY - b.lift - b.h + 4, bh = b.h - 8;
    if (px < bx + bw && px + pw > bx && py < by + bh && py + ph > by) { die(); break; }
  }
}
function drawDino() {
  var g = S.G, i;
  var sky = ctx.createLinearGradient(0, 0, 0, H); sky.addColorStop(0, '#ffb86b'); sky.addColorStop(0.55, '#ffe29a'); sky.addColorStop(1, '#fff3cf');
  ctx.fillStyle = sky; ctx.fillRect(0, 0, W, H);
  ctx.fillStyle = '#ff6b4a'; ctx.beginPath(); ctx.arc(270, 150, 42, 0, 6.3); ctx.fill();
  for (i = 0; i < 3; i++) cloud(((i * 230 - g.cx) % 620 + 620) % 620 - 60, 90 + i * 55, 0.9);
  ctx.fillStyle = '#c98f4f'; ctx.fillRect(0, D_GY, W, H - D_GY);
  ctx.fillStyle = '#1a0b45'; ctx.fillRect(0, D_GY, W, 4);
  ctx.fillStyle = '#9b6a35'; for (i = -1; i < 10; i++) { ctx.fillRect(i * 40 - g.gx + 6, D_GY + 18, 14, 4); ctx.fillRect(i * 40 - g.gx + 26, D_GY + 40, 8, 4); }
  for (i = 0; i < g.obs.length; i++) {
    var o = g.obs[i], oy = D_GY - o.lift - o.h;
    if (o.k === 'cactus') {
      ctx.fillStyle = '#2f9e44'; ctx.strokeStyle = '#1a0b45'; ctx.lineWidth = 2.5;
      var n = o.n, cw = o.w / n;
      for (var j = 0; j < n; j++) {
        var cx = o.x + j * cw, hh = o.h - (j % 2) * 8, ww = Math.min(cw - 3, 18);
        var bxx = cx + (cw - ww) / 2;
        ctx.fillRect(bxx, D_GY - hh, ww, hh); ctx.strokeRect(bxx, D_GY - hh, ww, hh);
        ctx.fillRect(bxx - 6, D_GY - hh * 0.6, 7, 6); ctx.fillRect(bxx + ww - 1, D_GY - hh * 0.75, 7, 6);
      }
    } else {
      var fl = Math.sin(g.t * 0.35) > 0;
      ctx.fillStyle = '#ff3d81'; ctx.strokeStyle = '#1a0b45'; ctx.lineWidth = 2.5;
      ctx.beginPath(); ctx.ellipse(o.x + 22, oy + 16, 18, 10, 0, 0, 6.3); ctx.fill(); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(o.x + 4, oy + 14); ctx.lineTo(o.x - 4, oy + 18); ctx.lineTo(o.x + 6, oy + 20); ctx.fill();
      ctx.fillStyle = '#ffd23f'; ctx.beginPath(); ctx.moveTo(o.x + 14, oy + 12); ctx.lineTo(o.x + 28, oy + (fl ? -6 : 34)); ctx.lineTo(o.x + 34, oy + 14); ctx.closePath(); ctx.fill(); ctx.stroke();
      ctx.fillStyle = '#fff'; ctx.fillRect(o.x + 9, oy + 11, 4, 4);
    }
  }
  var top = D_GY - g.y - D_H, run = g.y <= 0.5 && S.state === 'run', sw = run ? Math.sin(g.t * 0.6) * 5 : 0;
  ctx.strokeStyle = '#1a0b45'; ctx.lineWidth = 5; ctx.lineCap = 'round';
  ctx.beginPath(); ctx.moveTo(D_X + 14, top + 48); ctx.lineTo(D_X + 14 + sw, D_GY - g.y - 2);
  ctx.moveTo(D_X + 26, top + 48); ctx.lineTo(D_X + 26 - sw, D_GY - g.y - 2); ctx.stroke();
  face(S.sel[S.turn], D_X + D_W / 2, top + 25, D_W + 4, 52, 0, S.turn ? '#2de2e6' : '#ff3d81');
  if (S.state === 'ready') centerText('TAP TO JUMP', 150, 34, '#fff');
  if (S.state === 'dead') g.settle = 0;
}

show('welcome');
})();
